extern void install_LDP_L2VPN_NODE(void);

void install_LDP_L2VPN_NODE(void)

{
	unsigned node_id = LDP_L2VPN_NODE;
	struct cmd_node *node;

	assert(node_id < vector_active(cmdvec));
	node = vector_slot(cmdvec, node_id);
	assert(node);
	assert(vector_active(node->cmdgraph->nodes) == 1);
	graph_delete_node(node->cmdgraph, vector_slot(node->cmdgraph->nodes, 0));
	vector_free(node->cmdgraph->nodes);
	node->cmdgraph->nodes = &gvec_LDP_L2VPN_NODE;
	vector_set(node->cmd_vector, &ldp_bridge_cmd_vtysh);
	vector_set(node->cmd_vector, &ldp_member_interface_cmd_vtysh);
	vector_set(node->cmd_vector, &ldp_mtu_cmd_vtysh);
	vector_set(node->cmd_vector, &ldp_vc_type_cmd_vtysh);
	vector_set(node->cmd_vector, &no_ldp_member_pseudowire_cmd_vtysh);
}

